import{_ as n,o as s,c as a,e as t}from"./app-6be1f847.js";const p={},e=t(`<h3 id="一、核心区别与概念解析" tabindex="-1"><a class="header-anchor" href="#一、核心区别与概念解析" aria-hidden="true">#</a> 一、核心区别与概念解析</h3><h4 id="_1-基本定义与定位" tabindex="-1"><a class="header-anchor" href="#_1-基本定义与定位" aria-hidden="true">#</a> 1. 基本定义与定位</h4><ul><li><p><strong>Comparable（可比较的）</strong>：</p><ul><li>是一个<strong>内部比较器</strong>，也叫自然排序接口。</li><li>实现该接口的类会<strong>自身具备比较能力</strong>，相当于“对象自己知道怎么和同类型对象比大小”。</li><li>接口只有一个方法：<code>int compareTo(T o)</code>，返回值规则： <ul><li>正数：当前对象 &gt; 传入对象；</li><li>0：两者相等；</li><li>负数：当前对象 &lt; 传入对象。</li></ul></li></ul></li><li><p><strong>Comparator（比较器）</strong>：</p><ul><li>是一个<strong>外部比较器</strong>，也叫定制排序接口。</li><li>不修改原类的代码，通过<strong>外部类实现比较逻辑</strong>，相当于“找一个第三方裁判来判断两个对象的大小”。</li><li>核心方法：<code>int compare(T o1, T o2)</code>，返回值规则和 <code>compareTo</code> 一致；Java 8 后还新增了大量便捷的静态方法（如 <code>comparing</code>、<code>thenComparing</code>）。</li></ul></li></ul><h4 id="_2-代码示例对比" tabindex="-1"><a class="header-anchor" href="#_2-代码示例对比" aria-hidden="true">#</a> 2. 代码示例对比</h4><h5 id="示例1-使用-comparable-实现自然排序" tabindex="-1"><a class="header-anchor" href="#示例1-使用-comparable-实现自然排序" aria-hidden="true">#</a> 示例1：使用 Comparable 实现自然排序</h5><p>假设我们有一个 <code>Person</code> 类，希望按年龄自然排序：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 实现 Comparable 接口，指定比较的类型为 Person</span>
<span class="token keyword">class</span> <span class="token class-name">Person</span> <span class="token keyword">implements</span> <span class="token class-name">Comparable</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Person</span><span class="token punctuation">&gt;</span></span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token class-name">String</span> name<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> age<span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token keyword">int</span> age<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>name <span class="token operator">=</span> name<span class="token punctuation">;</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>age <span class="token operator">=</span> age<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// 实现 compareTo 方法，定义“自然排序规则”：按年龄升序</span>
    <span class="token annotation punctuation">@Override</span>
    <span class="token keyword">public</span> <span class="token keyword">int</span> <span class="token function">compareTo</span><span class="token punctuation">(</span><span class="token class-name">Person</span> o<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 简化写法：return this.age - o.age;（升序），o.age - this.age 为降序</span>
        <span class="token keyword">return</span> <span class="token class-name">Integer</span><span class="token punctuation">.</span><span class="token function">compare</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>age<span class="token punctuation">,</span> o<span class="token punctuation">.</span>age<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// getter/toString 省略</span>
    <span class="token annotation punctuation">@Override</span>
    <span class="token keyword">public</span> <span class="token class-name">String</span> <span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string">&quot;Person{name=&#39;&quot;</span> <span class="token operator">+</span> name <span class="token operator">+</span> <span class="token string">&quot;&#39;, age=&quot;</span> <span class="token operator">+</span> age <span class="token operator">+</span> <span class="token string">&quot;}&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token comment">// 测试 Comparable</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">CompareTest</span> <span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Person</span><span class="token punctuation">&gt;</span></span> list <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        list<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&quot;张三&quot;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        list<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&quot;李四&quot;</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        list<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&quot;王五&quot;</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// Collections.sort 直接支持实现 Comparable 的对象</span>
        <span class="token class-name">Collections</span><span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span>list<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;按年龄自然排序：&quot;</span> <span class="token operator">+</span> list<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">// 输出：[Person{name=&#39;李四&#39;, age=20}, Person{name=&#39;张三&#39;, age=25}, Person{name=&#39;王五&#39;, age=30}]</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="示例2-使用-comparator-实现定制排序" tabindex="-1"><a class="header-anchor" href="#示例2-使用-comparator-实现定制排序" aria-hidden="true">#</a> 示例2：使用 Comparator 实现定制排序</h5><p>如果想临时按姓名排序，且不想修改 <code>Person</code> 类（比如 <code>Person</code> 是第三方类），就用 <code>Comparator</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 无需修改 Person 类，外部定义比较规则</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">ComparatorTest</span> <span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Person</span><span class="token punctuation">&gt;</span></span> list <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        list<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&quot;张三&quot;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        list<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&quot;李四&quot;</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        list<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&quot;王五&quot;</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 方式1：匿名内部类实现 Comparator</span>
        <span class="token class-name">Collections</span><span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span>list<span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token class-name">Comparator</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Person</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token annotation punctuation">@Override</span>
            <span class="token keyword">public</span> <span class="token keyword">int</span> <span class="token function">compare</span><span class="token punctuation">(</span><span class="token class-name">Person</span> o1<span class="token punctuation">,</span> <span class="token class-name">Person</span> o2<span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token comment">// 按姓名升序（字符串的 compareTo 是按字典序）</span>
                <span class="token keyword">return</span> o1<span class="token punctuation">.</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">compareTo</span><span class="token punctuation">(</span>o2<span class="token punctuation">.</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;按姓名排序：&quot;</span> <span class="token operator">+</span> list<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">// 输出：[Person{name=&#39;李四&#39;, age=20}, Person{name=&#39;王五&#39;, age=30}, Person{name=&#39;张三&#39;, age=25}]</span>

        <span class="token comment">// 方式2：Java 8 简化写法（Lambda）</span>
        list<span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token class-name">Comparator</span><span class="token punctuation">.</span><span class="token function">comparing</span><span class="token punctuation">(</span><span class="token class-name">Person</span><span class="token operator">::</span><span class="token function">getName</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">reversed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 姓名降序</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;按姓名降序：&quot;</span> <span class="token operator">+</span> list<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">// 输出：[Person{name=&#39;张三&#39;, age=25}, Person{name=&#39;王五&#39;, age=30}, Person{name=&#39;李四&#39;, age=20}]</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="二、核心差异总结表" tabindex="-1"><a class="header-anchor" href="#二、核心差异总结表" aria-hidden="true">#</a> 二、核心差异总结表</h3><table><thead><tr><th>维度</th><th>Comparable</th><th>Comparator</th></tr></thead><tbody><tr><td>所属类型</td><td>内部比较器（自身实现）</td><td>外部比较器（第三方实现）</td></tr><tr><td>核心方法</td><td><code>compareTo(T o)</code></td><td><code>compare(T o1, T o2)</code></td></tr><tr><td>代码侵入性</td><td>需修改被比较类的源码（实现接口）</td><td>无需修改被比较类，灵活扩展</td></tr><tr><td>排序规则灵活性</td><td>只能定义<strong>一种</strong>排序规则（自然排序）</td><td>可定义<strong>多种</strong>排序规则，按需切换</td></tr><tr><td>使用场景</td><td>固定的、默认的排序逻辑</td><td>临时的、定制化的排序逻辑</td></tr><tr><td>典型使用方式</td><td><code>Collections.sort(list)</code></td><td><code>Collections.sort(list, comparator)</code></td></tr></tbody></table><h3 id="三、使用建议" tabindex="-1"><a class="header-anchor" href="#三、使用建议" aria-hidden="true">#</a> 三、使用建议</h3><ol><li>如果一个类的排序逻辑是“固定的、天然的”（比如数字的大小、字符串的字典序），让类实现 <code>Comparable</code>；</li><li>如果排序逻辑是“多变的、临时的”，或者无法修改原类（如第三方类），使用 <code>Comparator</code>；</li><li>Java 8 后优先使用 <code>Comparator</code> 的静态方法（如 <code>comparing</code>、<code>thenComparing</code>）+ Lambda，代码更简洁。</li></ol><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> 总结</h3><ol><li><code>Comparable</code> 是<strong>对象自身具备比较能力</strong>，通过 <code>compareTo</code> 实现，排序规则固定，需修改原类；</li><li><code>Comparator</code> 是<strong>外部定制比较规则</strong>，通过 <code>compare</code> 实现，灵活无侵入，支持多规则排序；</li><li>实际开发中，<code>Comparator</code> 因灵活性更常用，尤其是 Java 8 后的 Lambda 写法大幅简化了其使用成本。</li></ol>`,16),o=[e];function c(l,i){return s(),a("div",null,o)}const r=n(p,[["render",c],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/java/Comparator_vs_Comparable.html.vue"]]);export{r as default};
